'use strict';
(() => {
let files=[], results=[], waves=[];
function csv(text){let rows=[],row=[],cell='',q=false;text=text.replace(/^\uFEFF/,'');for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(q&&text[i+1]==='"'){cell+='"';i++;}else q=!q;}else if(c===','&&!q){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(s=>s.trim()))rows.push(row);row=[];cell='';}else cell+=c;}if(q)throw Error('닫히지 않은 CSV 따옴표가 있습니다.');row.push(cell);if(row.some(s=>s.trim()))rows.push(row);if(rows.length<2)throw Error('헤더와 데이터 행이 필요합니다.');const keys=rows.shift().map(s=>s.trim());if(new Set(keys).size!==keys.length)throw Error('중복 열 이름이 있습니다.');return rows.map((r,i)=>{if(r.length!==keys.length)throw Error(`${i+2}행 열 개수가 다릅니다.`);return Object.fromEntries(keys.map((k,j)=>[k,r[j]]));});}
const num=(v,name)=>{if(v===null||v===undefined||String(v).trim()===''||!Number.isFinite(Number(v)))throw Error(`${name}: 숫자가 필요합니다.`);return Number(v);};
function analyze(rows,start,target,band){if(!(target>start&&band>0))throw Error('목표는 시작 압력보다 커야 하며 허용 오차는 양수여야 합니다.');let groups=new Map();rows.forEach(r=>{let key=String(r.id||'가져온 실험');if(!groups.has(key))groups.set(key,[]);groups.get(key).push(r);});return Array.from(groups,([id,rs])=>{const waveform='time_s'in rs[0]&&'pressure_mTorr'in rs[0];let peak=null,over,settle,end=null,samples=null,kp=rs[0].kp??'',ki=rs[0].ki??'';if(waveform){samples=rs.map(r=>[num(r.time_s,'time_s'),num(r.pressure_mTorr,'pressure_mTorr')]).sort((a,b)=>a[0]-b[0]);if(samples.length<2||samples[0][0]!==0)throw Error(id+': 시간 0부터 두 점 이상 필요합니다.');for(let i=0;i<samples.length;i++){if(samples[i][1]<0)throw Error('압력은 음수가 될 수 없습니다.');if(i&&samples[i][0]<=samples[i-1][0])throw Error(id+': 시간이 중복됩니다.');}peak=samples.reduce((v,r)=>Math.max(v,r[1]),-Infinity);end=samples.at(-1)[0];let last=-1;samples.forEach((r,i)=>{if(Math.abs(r[1]-target)>band+1e-9)last=i;});const candidate=samples[last+1]?.[0];settle=candidate!==undefined&&end-candidate>=2?candidate:null;over=Math.max(0,peak-target)/(target-start)*100;}else{if(rs.length!==1)throw Error(id+': 요약 데이터의 id는 고유해야 합니다.');over=num(rs[0].overshoot_step_pct,'overshoot_step_pct');settle=rs[0].settling_s===null||String(rs[0].settling_s??'').trim()===''?null:num(rs[0].settling_s,'settling_s');if(over<0||(settle!==null&&settle<0))throw Error('초과율·시간은 음수가 될 수 없습니다.');}const status=waveform&&end<30?'관찰 부족 (30초 미만)':over>5?'압력 초과':settle===null?'안정화 미확인':settle>5?'시간 초과':'목표 달성';return {row:{id,kp,ki,peak_mTorr:peak,overshoot_step_pct:over,settling_s:settle,duration_s:end,status,basis:waveform?'업로드 파형 계산':'입력 요약값 (파형 미검증)'},samples};});}
window.FileAnalysis={csv,analyze};
function save(name,data,type){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([data],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function outCSV(name,rows){if(!rows.length)return;const esc=v=>'"'+String(v??'').replace(/^[=+@\-]/,"'$&").replaceAll('"','""')+'"';const keys=Object.keys(rows[0]);save(name,'\uFEFF'+[keys.map(esc).join(','),...rows.map(r=>keys.map(k=>esc(r[k])).join(','))].join('\r\n'),'text/csv;charset=utf-8');}
function render(){const table=document.createElement('table'),head=document.createElement('tr');['파일 / 조건','Kp','Ki','초과율(%)','안정화(초)','판정','근거'].forEach(s=>{const th=document.createElement('th');th.textContent=s;head.append(th);});table.append(head);results.forEach(r=>{const tr=document.createElement('tr');[r.file+' / '+r.id,r.kp,r.ki,r.overshoot_step_pct.toFixed(2),r.settling_s===null?'미확인':r.settling_s.toFixed(2),r.status,r.basis].forEach(s=>{const td=document.createElement('td');td.textContent=s;tr.append(td);});table.append(tr);});$('import-table').replaceChildren(table);$('import-selection').replaceChildren(...waves.map((r,i)=>{const o=document.createElement('option');o.value=i;o.textContent=r.file+' / '+r.id;return o;}));let eligible=results.filter(r=>r.status==='목표 달성');eligible.sort((a,b)=>a.settling_s-b.settling_s);$('import-insight').textContent=results.length?`${results.length}조건 중 ${eligible.length}조건이 기준을 만족합니다.`+(eligible.length?` 만족 조건 중 가장 빠른 것은 ${eligible[0].id} (${eligible[0].settling_s.toFixed(2)}초)입니다.`:'')+' 파일의 실측 여부는 사용자가 확인해야 합니다.':'';$('export-import').disabled=!results.length;$('export-raw').disabled=!files.length;plot();}
function run(){try{let next=[],nw=[];const start=num($('file-start').value,'시작 압력'),target=num($('file-target').value,'목표 압력'),band=num($('file-band').value,'허용 오차');for(const f of files){for(const a of analyze(f.rows,start,target,band)){next.push({file:f.name,...a.row});if(a.samples)nw.push({file:f.name,id:a.row.id,samples:a.samples});}}results=next;waves=nw;render();$('import-message').textContent=`${files.length}개 파일 분석 완료. 가져온 데이터는 시뮬레이션 기록과 별도로 비교합니다.`;}catch(e){results=[];waves=[];render();$('import-message').textContent='분석 불가: '+e.message;}}
async function ingest(list){try{const pending=[];for(const f of list){if(f.size>10*1024*1024)throw Error(f.name+': 10MB 제한을 넘었습니다.');const text=await f.text();let rows;if(/\.csv$/i.test(f.name))rows=csv(text);else if(/\.json$/i.test(f.name)){const obj=JSON.parse(text);rows=Array.isArray(obj)?obj:obj.experiments;if(!Array.isArray(rows))throw Error('JSON은 객체 배열 또는 experiments 배열이어야 합니다.');}else throw Error('CSV 또는 JSON 파일을 선택하세요.');if(!rows.length||rows.some(r=>!r||typeof r!=='object'||Array.isArray(r)))throw Error('유효한 데이터 행이 없습니다.');pending.push({name:f.name,rows});}if([...files,...pending].reduce((n,f)=>n+f.rows.length,0)>100000)throw Error('총 100,000행 제한을 넘었습니다.');files.push(...pending);run();}catch(e){$('import-message').textContent='가져오기 실패: '+e.message;}}
function plot(){const el=$('import-plot'),c=el.getContext('2d'),w=el.clientWidth||800,h=280;el.width=w*2;el.height=h*2;c.scale(2,2);c.font='14px Pretendard';const wave=waves[Number($('import-selection').value)||0];if(!wave){c.fillStyle='#606c80';c.fillText('파형 파일을 넣으면 시간에 따른 압력을 볼 수 있습니다.',20,50);return;}const pts=wave.samples,target=Number($('file-target').value),lo=Math.min(target, ...pts.filter((_,i)=>i%Math.max(1,Math.ceil(pts.length/10000))===0).map(r=>r[1]))-1;let hi=target;for(const p of pts)hi=Math.max(hi,p[1]);hi+=1;const x=t=>50+t/pts.at(-1)[0]*(w-70),y=p=>235-(p-lo)/(hi-lo)*210;c.strokeStyle='#ccd5e8';c.strokeRect(50,25,w-70,210);c.fillStyle='#606c80';c.fillText('압력 (mTorr)',50,17);c.fillText('0초',40,260);c.fillText(pts.at(-1)[0]+'초',w-65,260);c.fillText(hi.toFixed(1),0,30);c.fillText(lo.toFixed(1),0,235);c.setLineDash([4,4]);c.strokeStyle='#008252';c.beginPath();c.moveTo(50,y(target));c.lineTo(w-20,y(target));c.stroke();c.setLineDash([]);c.strokeStyle='#1428a0';c.beginPath();pts.forEach((r,i)=>{if(i)c.lineTo(x(r[0]),y(r[1]));else c.moveTo(x(r[0]),y(r[1]));});c.stroke();}
$('file-input').onchange=e=>ingest(e.target.files);const drop=$('file-drop');drop.ondragover=e=>{e.preventDefault();drop.classList.add('drag');};drop.ondragleave=()=>drop.classList.remove('drag');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('drag');ingest(e.dataTransfer.files);};$('reanalyze').onclick=run;$('import-selection').onchange=plot;window.addEventListener('resize',plot);document.querySelector('[data-tab="files"]').addEventListener('click',()=>requestAnimationFrame(plot));$('clear-import').onclick=()=>{files=[];results=[];waves=[];render();$('import-message').textContent='가져온 파일을 비웠습니다.';$('file-input').value='';};$('export-import').onclick=()=>outCSV('import_analysis.csv',results);$('export-raw').onclick=()=>save('import_original.json',JSON.stringify(files.flatMap(f=>f.rows),null,2),'application/json');$('sample-wave').onclick=()=>outCSV('waveform_example.csv',M.simulate(21).map(r=>({id:'example_E22',kp:.25,ki:.1,time_s:r[0],pressure_mTorr:r[1]})));$('sample-summary').onclick=()=>outCSV('summary_example.csv',D.experiments.slice(0,2));$('export-session').onclick=()=>{if(!observed.length){$('export-message').textContent='장비 조작에서 먼저 실험을 실행하세요.';return;}outCSV('my_experiments.csv',observed);$('export-message').textContent='실행한 실험 기록을 저장했습니다.';};$('export-all').onclick=()=>outCSV('reference_25.csv',D.experiments);$('export-wave').onclick=()=>{const gains=M.grid[currentIndex];outCSV('current_waveform.csv',trace.map(r=>({id:'current',kp:gains[0],ki:gains[1],time_s:r[0],pressure_mTorr:r[1],valve_open_fraction:r[2]})));$('export-message').textContent='현재 선택된 조건의 전체 계산 파형을 저장했습니다.';};
})();
